<?php
declare(strict_types=1);
use Berserk\Core\{Db,GameRepository,CommandJournalRepository,GameState,Result,DbQueryException,Dice};
$branches=($argv[2]??'')==='branches';ob_start();if($branches){$GLOBALS['capture_pairs']=true;require __DIR__.'/test_coverage_closure_journal.php';}else{define('CAPTURE_INTEGRATIONS',true);require __DIR__.'/test_integration_closure_journal.php';}ob_end_clean();
$db=new Db(require __DIR__.'/../config/db.php');$identity=$db->fetchOne('SELECT @@port p,DATABASE() d');if((int)$identity['p']!==33671||!preg_match('/^lobby_[0-9]+$/D',$identity['d']))throw new RuntimeException('Wrong disposable DB');
$repo=new GameRepository($db);$journal=new CommandJournalRepository($db);$game=(int)$argv[1];if($branches||($argv[2]??'')==='fresh'){$parent=$repo->findById($game);$fresh=$repo->create($parent->hostId,$parent->playerId);$game=$fresh->gameId;}$admin=new Db(['host'=>'127.0.0.1:33671','user'=>'root','pass'=>'','name'=>$identity['d']]);$done=[];$number=0;
foreach($GLOBALS['captured_pairs']as$name=>[$seed,$run,$verify,$queue]){if(!$branches&&!preg_match('/^[1-9]/',$name))continue;$s=$repo->findById($game);$key=($branches?'closure-branch-':'closure-integration-').(++$number);$entry=$journal->registerProcessing($game,'host',$key,'closure_chain',[],$s->persistenceVersion);
 $apply=function(GameState $working)use($seed,$run,$queue){$rec=$working->historyRecorder;$copy=GameState::fromArray($seed->toArray());foreach(['host','player']as$side)$copy->players[$side]->userId=$working->players[$side]->userId;foreach(get_object_vars($copy)as$k=>$v)if(!in_array($k,['gameId','hostId','playerId','persistenceVersion','persistenceJson','historyRecorder','journalSchema'],true))$working->$k=$v;$working->historyRecorder=$rec;$rec->statusBaseline($working);$_SESSION=['debug_roll'=>$queue];Dice::init();$run($working);$rec->commandFinished($working,Result::ok());return Result::ok();};
 $before=$db->fetchOne('SELECT json,version FROM games WHERE ind='.$game);$count=$db->fetchOne('SELECT COUNT(*) n FROM battle_history_events WHERE game_id='.$game);$fault=false;
 $admin->query('ALTER TABLE battle_history_events ADD CONSTRAINT closure_fault CHECK(journal_id <> '.(int)$entry['id'].')');try{$repo->executeLockedCommand($s,$journal,(int)$entry['id'],$apply);}catch(DbQueryException){$fault=true;}finally{$admin->query('ALTER TABLE battle_history_events DROP CONSTRAINT closure_fault');}
 check($fault&&$before===$db->fetchOne('SELECT json,version FROM games WHERE ind='.$game)&&$count===$db->fetchOne('SELECT COUNT(*) n FROM battle_history_events WHERE game_id='.$game),'atomic rollback '.$name);
 $repo->executeLockedCommand($s,$journal,(int)$entry['id'],$apply);$rows=$db->fetchAll('SELECT event_type,host_json,player_json,public_json,payload_json FROM battle_history_events WHERE journal_id='.(int)$entry['id'].' ORDER BY event_seq');check(count($rows)>0,'saved chain '.$name);
 $events=array_map(fn($e)=>['type'=>$e['event_type'],'payload'=>json_decode($e['payload_json'],true),'host'=>json_decode($e['host_json']??'null',true),'player'=>json_decode($e['player_json']??'null',true),'public'=>json_decode($e['public_json']??'null',true)],$rows);$verify($events,$repo->findById($game));$again=$journal->registerProcessing($game,'host',$key,'closure_chain',[],$s->persistenceVersion);check(!$again['is_new']&&$again['status']==='committed','retry '.$name);$done[]=['scenario'=>$name,'rollback'=>true,'retry'=>true,'saved_events'=>count($rows)];
}
echo json_encode(['status'=>'PASS','chains'=>$done],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);
